#!/usr/bin/env python3
"""
patch_L421_1_served_hover_words_20261006.py -- GALLERY repo. The facts
five Earth hovers state move out of the drawing code into the served
words, with their sources. No word a visitor reads changes.

Built on gallery 8487b0f84ae8ba375e24ff20e9806a1214bcb3a0 at
https://github.com/tonylquintanilla/tonyquintanilla.github.io
(orrery fbd223eee7cb8823439c17d64fa23bb5e04110eb at
https://github.com/tonylquintanilla/palomas_orrery), from
documentation/MANIFEST_L421_typed_facts_20261006.md in the orrery repo.

HOW TO RUN IT
    Save this file in the GALLERY repo's root folder (the one with
    interactive.html and daily_run.py), open it in VS Code, click Run.
    Then follow the numbered steps it prints. The order matters: this
    patch changes data/objects_config.json, and the rooms draw from the
    served cache, so the cache builder runs BEFORE the maintenance run
    and the commit.

WHAT CHANGES (L-421, items E5 to E10 of the manifest)
    data/objects_config.json
        The geostationary ring, magnetopause, bow shock and magnetotail
        each gain a `hover` word: the sentences their hovers state about
        nature or a paper, in the words they have today, with {name}
        where a served number goes. Earth's belts gain three parallel
        lists, hovers_band, hovers_rings and hovers_plane, the same way.
        Two sources grow by a sentence: the ring's names NASA Earth
        Observatory's Catalog of Earth Satellite Orbits for "keep pace
        with Earth's turning"; the magnetic tilt's says why the magnetic
        equator turns with Earth (the IGRF paper puts the magnetic pole
        at a fixed place on the ground).
    gallery/feature_renderers.js
        servedHover() prints those words and fills in the numbers. If a
        word is missing it warns and prints nothing there; nothing typed
        stands in for it.
    tools/store_writer.py, tools/exhibit_store_editor.py
        `hover` is a word the writer saves and the editor window shows;
        the belts' three lists are belt words the writer saves.
    documentation/payload_earth_scene.json  re-recorded whole by
        tools/record_earth_scene.py, so it carries the new words
        (recorded on the cache of 2026-10-06).
    documentation/payload_earth.json  the older fixture, re-written
        whole with the new words added and nothing else changed.
    documentation/fixture_hovers_L421_on_8487b0f8.json  the hover
        fixture, re-recorded. Six hovers differ from the L-349 one: the
        magnetopause and bow shock (the same words, two line breaks
        moved) and the Sun direction and three Moon hovers (the newer
        scene date). documentation/smoke_display_figures.js reads it.

SUCCESS looks like: one "ok" line per change, then "patch applied".
FAILURE looks like: one ERROR: or ANCHOR FAIL: line, and NOTHING is
written. Undo is Discard Changes in GitHub Desktop.

Written October 6, 2026 with Anthropic's Claude Opus 5.5.
"""

