                                            '{"object": "earth", "feature": "earth_geostationary", '
                                            '"params": {"geostationary_ring": {"name": '
                                            '"Geostationary Belt (GEO)", "description": "A ring of '
                                            'satellites 35,786 km above the equator that circle '
                                            'exactly as fast as Earth turns, so each hangs over '
                                            'one spot.", "about": "Satellites in the geostationary '
                                            "belt orbit once a day, matching Earth's rotation, and "
                                            'so stay fixed over a point on the equator. Several '
                                            'hundred of them carry television, weather imagery and '
                                            'communications for much of the world. In April 2029 '
