                                            '"info_url": '
                                            '"https://en.wikipedia.org/wiki/Geostationary_orbit", '
                                            '"hover": "A ring in the equatorial plane, not a '
                                            "sphere: satellites here keep pace with Earth's "
                                            'turning and hang over one longitude.", "color": '
                                            '"rgb(220, 220, 255)", "opacity": 0.6, "n_points": '
                                            '120, "marker_size": 2.0, "source": "Derived: (GM_E / '
                                            'omega^2)^(1/3) from IERS Conventions (2010) TN36 '
                                            'Table 1.1 -- GM_E = 3.986004418e14 m^3 s^-2, nominal '
                                            'mean angular velocity 7.292115e-5 rad s^-1. The '
