                                            '{"object": "earth", "feature": "earth_magnetosphere", '
                                            '"params": {"_comment": "The orrery emits '
                                            'magnetopause, bow shock, inner belt and outer belt '
                                            'from ONE call. Served as four rows: the two standoffs '
                                            'here, the two belts in van_allen_belts. Renderer for '
                                            'the standoff shapes is step 3.", "magnetopause": '
                                            '{"name": "Magnetopause", "description": "The outer '
                                            "boundary of Earth's magnetic field, where it holds "
                                            'off the solar wind: pressed in by day, trailing a '
                                            'long tail by night.", "about": "Earth\'s magnetic '
                                            'field carves a cavity in the solar wind called the '
                                            'magnetosphere. On the side facing the Sun the wind '
                                            'presses it in; on the night side it stretches into a '
                                            "magnetotail observed far beyond the Moon's distance. "
                                            'The magnetopause is that boundary. It deflects the '
                                            'solar wind and turns aside many of the charged '
                                            'particles that reach Earth from the Sun and from '
                                            'beyond the solar system. The surface drawn is a model '
                                            'for a quiet solar wind; the real boundary moves in '
                                            'and out as the wind\'s pressure changes.", "shape": '
                                            '"magnetopause", "surface": {"_model": "Shue et al. '
                                            '(1998) eq. 10 with eq. 11. r = r0 [2 / (1 + cos '
                                            'theta)]^alpha, theta measured from the Sun-Earth '
                                            'line, r0 the standoff below. The geometry evaluates '
                                            'alpha = (a6 + a7 Bz)(1 + a8 ln Dp) from the rows '
                                            'here; alpha gets no row of its own because no text on '
                                            'the page prints it. At the declared conditions alpha '
                                            'is 0.59 -- two figures, because a6 is 0.58 +/- 0.01 '
                                            'and that carries straight through.", "a6": {"value": '
                                            '0.58, "unit": "flaring_exponent", "uncertainty": '
                                            '"0.01", "figures": 2, "source": "Shue et al. (1998), '
                                            'doi:10.1029/98JA01103 -- Table 1 (After Fit) row a6, '
                                            'p. 17,698: 0.58 +/- 0.01. The leading term of eq. '
                                            '11.", "orrery_constant": '
                                            '"constants_new.py::EARTH_MAGNETOPAUSE_SHUE_A6"}, '
                                            '"a7": {"value": -0.007, "unit": "per_nt", '
                                            '"uncertainty": "0.0005", "figures": 1, "source": '
                                            '"Shue et al. (1998), doi:10.1029/98JA01103 -- Table 1 '
                                            '(After Fit) row a7, p. 17,698: -0.007 +/- 0.0005 per '
                                            'nT. Eq. 11 prints it as a subtraction; the table '
                                            'carries the sign, so this value is negative and '
                                            'adds.", "orrery_constant": '
                                            '"constants_new.py::EARTH_MAGNETOPAUSE_SHUE_A7_PER_NT"}, '
                                            '"a8": {"value": 0.024, "unit": '
                                            '"log_pressure_coefficient", "uncertainty": "0.0004", '
                                            '"figures": 2, "source": "Shue et al. (1998), '
                                            'doi:10.1029/98JA01103 -- Table 1 (After Fit) row a8, '
                                            'p. 17,698: 0.024 +/- 0.0004. The pressure term of eq. '
                                            '11.", "orrery_constant": '
                                            '"constants_new.py::EARTH_MAGNETOPAUSE_SHUE_A8"}, '
                                            '"bz": {"value": 0.0, "unit": "nt", "prints": 1, '
                                            '"figures": "exact", "_declared": "A neutral midpoint '
                                            'chosen for this scene, NOT a figure from the paper. '
