                                            'so the two surfaces can be compared.", '
                                            '"orrery_constant": '
                                            '"constants_new.py::EARTH_SOLAR_WIND_BZ_NT"}, '
                                            '"pressure": {"value": 2.0, "unit": "npa", "prints": '
