                                            'dynamic pressure both fits are evaluated at. Declared '
                                            'for this scene, not measured.", "orrery_constant": '
                                            '"constants_new.py::EARTH_SOLAR_WIND_PRESSURE_NPA"}, '
                                            '"cut_angle": {"value": 120.0, "unit": "deg", '
                                            '"prints": 3, "figures": "exact", "_declared": "Where '
                                            'the drawn surface stops, measured from the nose. '
                                            "Shue's surface has no end: at this flaring the radius "
                                            'grows without bound as theta approaches 180 degrees, '
                                            'so a drawing must choose a stop. Shue et al. (1998) '
