                                            'limit, not an edge.", "orrery_constant": '
                                            '"constants_new.py::EARTH_MAGNETOPAUSE_CUT_ANGLE_DEG"}}, '
                                            '"standoff": {"value": 10.3, "unit": "r_earth", "in": '
                                            '{"au": {"value": 0.00044, "figures": 2, "prints": '
