                                            'Geophys. Res. 103:17691, doi:10.1029/98JA01103 -- eq. '
                                            '10 evaluated at the declared conditions (Bz = 0 nT, '
                                            'Dp = 2 nPa). Corroboration: Lugaz et al. (2016), '
                                            'doi:10.1038/ncomms13001 -- typical subsolar '
                                            'magnetopause 9-11 R_E, which contains this.", '
                                            '"orrery_constant": '
                                            '"constants_new.py::EARTH_MAGNETOPAUSE_STANDOFF_RADII", '
                                            '"note": "Quiet-time nominal. Under storm compression '
                                            'it can fall inside geostationary orbit (6.6 R_E)."}, '
                                            '"bow_shock": {"name": "Bow Shock", "description": '
                                            '"The shock wave where the supersonic solar wind first '
                                            "slows as it hits Earth's magnetic field, like the bow "
                                            'wave of a boat.", "about": "The solar wind moves '
                                            'faster than sound travels through the thin gas of '
                                            "space, so when it meets Earth's magnetic field it "
                                            'cannot flow smoothly around it: a standing shock '
                                            'forms upstream, sunward of the magnetopause, where '
                                            'the wind slows and heats. The surface drawn is a '
                                            'model for a quiet solar wind, and real crossings '
                                            'scatter around it.", "shape": "bow_shock", "surface": '
                                            '{"_model": "Jelinek et al. (2012), the paraboloid of '
                                            'eqs. 15-16 parameterised by tau: x = R0 p^(-1/eps) - '
                                            'tau^2 / 2, and the distance from the Sun-Earth line '
                                            'is sqrt(2 R0 p^(-1/eps)) tau / lambda. At tau = 0 '
                                            'this is the standoff below. A different functional '
                                            'form from the magnetopause because it is a different '
                                            'paper\'s fit, not a variation on Shue.", "r0": '
                                            '{"value": 15.02, "unit": "r_earth", "in": {"au": '
                                            '{"value": 0.00064, "figures": 3, "prints": null}, '
                                            '"km": {"value": 95800.0, "figures": 3, "prints": '
