                                            '"figures": 4, "prints": null}, "r_sun": {"value": '
                                            '0.1377, "figures": 4, "prints": null}}, "figures": 4, '
                                            '"source": "Jelinek, Nemecek and Safrankova (2012), J. '
                                            'Geophys. Res. 117:A05208, doi:10.1029/2011JA017252 -- '
                                            'eq. 14, p. 5: R_BS = 15.02 p^(-1/6.55), so 15.02 R_E '
                                            'is the bow shock standoff at p = 1 nPa.", '
                                            '"orrery_constant": '
                                            '"constants_new.py::EARTH_BOW_SHOCK_JELINEK_R0_RADII"}, '
                                            '"epsilon": {"value": 6.55, "unit": '
                                            '"inverse_exponent", "figures": 3, "source": "Jelinek '
                                            'et al. (2012), doi:10.1029/2011JA017252 -- eq. 14, p. '
                                            '5: the pressure exponent of R_BS = 15.02 '
                                            'p^(-1/6.55).", "orrery_constant": '
                                            '"constants_new.py::EARTH_BOW_SHOCK_JELINEK_EPS"}, '
                                            '"lambda": {"value": 1.17, "unit": "shape_factor", '
                                            '"figures": 3, "source": "Jelinek et al. (2012), '
                                            'doi:10.1029/2011JA017252 -- sec. 4, in the text after '
                                            'eq. 11: lambda = 1.17 for the bow shock. Their '
                                            'magnetopause lambda of 1.54 is deliberately not used '
                                            'here, because this page\'s magnetopause is Shue\'s.", '
                                            '"orrery_constant": '
                                            '"constants_new.py::EARTH_BOW_SHOCK_JELINEK_LAMBDA"}, '
                                            '"pressure": {"value": 2.0, "unit": "npa", "prints": '
                                            '1, "figures": "exact", "_declared": "The same '
                                            'declared pressure as the magnetopause. Both surfaces '
                                            'must be evaluated at the same conditions or their '
                                            'relative positions mean nothing.", "orrery_constant": '
                                            '"constants_new.py::EARTH_SOLAR_WIND_PRESSURE_NPA"}, '
                                            '"cut_angle": {"value": 105.0, "unit": "deg", '
                                            '"prints": 3, "figures": "exact", "_declared": "Where '
                                            'the drawn surface stops, measured from the nose. '
                                            'Jelinek et al. fitted crossings within 7 hours of '
                                            "local noon either side, and 7 hours of Earth's turn "
