                                            'was, not by where the formula fails -- the opposite '
                                            'reason from the magnetopause\'s 120.", '
                                            '"orrery_constant": '
                                            '"constants_new.py::EARTH_BOW_SHOCK_CUT_ANGLE_DEG"}}, '
                                            '"standoff": {"value": 13.5, "unit": "r_earth", "in": '
                                            '{"au": {"value": 0.00058, "figures": 2, "prints": '
