                                            '"figures": 3, "prints": null}, "r_sun": {"value": '
                                            '0.124, "figures": 3, "prints": null}}, "figures": 3}, '
                                            '"scatter": {"value": 0.69, "unit": "r_earth", "in": '
                                            '{"au": {"value": 2.9e-05, "figures": 2, "prints": '
                                            'null}, "km": {"value": 4400.0, "figures": 2, '
