                                            '"constants_new.py::EARTH_BOW_SHOCK_JELINEK_SCATTER_RADII"}, '
                                            '"info_url": '
                                            '"https://en.wikipedia.org/wiki/Bow_shocks_in_astrophysics", '
                                            '"hover": "Jelinek et al. (2012), at dynamic pressure '
                                            '{pressure} nPa\\nDrawn to {cut_angle} deg from the '
                                            'nose, which is how far round the crossings the fit '
