                                            'eq. 14, R_BS = 15.02 p^(-1/6.55), evaluated at the '
                                            'declared pressure of 2 nPa. The paper states no '
                                            'uncertainty on its fitted numbers; how far real '
                                            'crossings fall from the fit (fig. 7) is given in the '
                                            'hover. Corroboration: Lugaz et al. (2016), Nat. '
                                            'Commun. 7:13001, doi:10.1038/ncomms13001 -- 11-14 R_E '
                                            'subsolar under normal solar wind, which contains '
                                            'this.", "orrery_constant": '
                                            '"constants_new.py::EARTH_BOW_SHOCK_STANDOFF_RADII", '
                                            '"note": "Quiet-time nominal, at the same declared '
                                            'solar wind pressure as the magnetopause. An earlier '
                                            'note here cited Farris & Russell (1994) for the model '
                                            'FORM; that was a miscitation -- it is a relation for '
                                            'the standoff at a given Mach number and takes '
                                            'obstacle shape as an input, not a shape model. '
                                            'Removed 2026-09-12 (L-305)."}, "magnetotail": '
                                            '{"name": "Magnetotail", "description": "Earth\'s '
                                            'magnetic field, drawn out by the solar wind into a '
                                            'long tail on the night side.", "about": "The solar '
                                            "wind drags Earth's magnetic field out behind the "
                                            'planet into a long tail. Spacecraft crossing it far '
                                            'downstream found that it stops widening about 120 '
                                            'Earth radii behind Earth and is about 60 Earth radii '
                                            'across beyond there. ISEE-3 followed it out to 220 '
                                            'Earth radii, which is how far the spacecraft went '
                                            'rather than where the tail ends. The tail is drawn '
                                            'round, which is close to its shape on average; at any '
                                            'moment it is often flattened, in a direction set by '
                                            "the solar wind's own magnetic field, which keeps "
                                            'changing.", "_declared": "The tail continues Shue\'s '
                                            'magnetopause surface from where the drawing of that '
